package org.sleepwell.app;
import android.content.*;import org.json.*;
/** Device-keystore protected connection settings, excluded from portable records/settings profiles. */
final class HueBridgeSettings {
 private static final String FILE="hue_bridge_v1";private static final Object LOCK=new Object();
 static SharedPreferences prefs(Context context){return context.getApplicationContext().getSharedPreferences(FILE,Context.MODE_PRIVATE);}
 static HueBridgeConfig load(Context context)throws Exception{SharedPreferences saved=prefs(context);long revision=saved.getLong("revision",0);String sealed=saved.getString("config","");if(sealed.isEmpty())return HueBridgeConfig.empty().revision(revision);JSONObject row=new JSONObject(new AutomationSecrets().open(sealed));if(row.length()!=10||SoundEventBackup.whole(row,"version")!=1)throw new IllegalStateException("Saved bridge configuration is unsupported.");HueBridgeConfig result=new HueBridgeConfig(row.getString("address"),row.getString("identity"),row.getString("pin"),row.getString("key"),row.getString("light"),row.getString("name"),saved.getBoolean("enabled",false),row.getInt("minutes"),row.getInt("maximum"),row.getBoolean("restore"),revision);result.validate();return result;}
 static HueBridgeConfig save(Context context,HueBridgeConfig config)throws Exception{config.validate();String sealed=new AutomationSecrets().seal(new JSONObject().put("version",1).put("address",config.address).put("identity",config.identity).put("pin",config.pin).put("key",config.key).put("light",config.light).put("name",config.name).put("minutes",config.minutes).put("maximum",config.maximum).put("restore",config.restore).toString());synchronized(LOCK){SharedPreferences saved=prefs(context);if(saved.getLong("revision",0)!=config.revision)throw new IllegalStateException("Bridge settings changed. Reopen before saving.");if(config.revision==Long.MAX_VALUE)throw new IllegalStateException("Bridge settings revision is unavailable.");if(config.enabled&&homeAssistant(context))throw new IllegalStateException("Turn off the Home Assistant lamp path before enabling direct Hue.");long revision=config.revision+1;if(!saved.edit().putString("config",sealed).putBoolean("enabled",config.enabled).putLong("revision",revision).putString("status",config.enabled?"Ready for a future real alarm. No lamp was changed by Save.":"Off. No automatic bridge requests.").commit())throw new IllegalStateException("Bridge settings were not saved.");return config.revision(revision);}}
 static void disconnect(Context context,long expected){synchronized(LOCK){SharedPreferences saved=prefs(context);long revision=saved.getLong("revision",0);if(revision!=expected||revision==Long.MAX_VALUE)throw new IllegalStateException("Bridge settings changed. Reopen before disconnecting.");if(!saved.edit().remove("config").putBoolean("enabled",false).putLong("revision",revision+1).putString("status","Disconnected locally. Revoke the app user in the Hue app if required; no bridge deletion was sent.").commit())throw new IllegalStateException("Bridge settings were not cleared.");}}
 static boolean homeAssistant(Context context){try{return SmartLightSettings.factory.preferences(context).getBoolean("enabled",false);}catch(RuntimeException unreadable){return true;}}
 static boolean current(Context context,long revision,boolean requireEnabled){try{SharedPreferences saved=prefs(context);return saved.getLong("revision",-1)==revision&&(!requireEnabled||saved.getBoolean("enabled",false))&&!homeAssistant(context);}catch(RuntimeException invalid){return false;}}
 static boolean enabled(Context context){try{return prefs(context).getBoolean("enabled",false);}catch(RuntimeException unreadable){return false;}}
 static void status(Context context,long revision,String message){if(prefs(context).getLong("revision",-1)==revision)prefs(context).edit().putString("status",message).apply();}
 static String status(Context context){try{return prefs(context).getString("status","Off · no bridge is paired.");}catch(RuntimeException invalid){return "Bridge settings need review.";}}
 private HueBridgeSettings(){}
}
